describe("deleteUnusedV3Tags", () => {
  test("deletes the workspace's unused tags and reports how many", async () => {
    grantAccess();
    vi.mocked(deleteUnusedTags).mockResolvedValue({ ok: true, data: { deletedCount: 3 } });

    const response = await deleteUnusedV3Tags({ ...base, workspaceId });
    const body = await response.json();

    expect(response.status).toBe(200);
    expect(body.data).toEqual({ deletedCount: 3 });
    expect(deleteUnusedTags).toHaveBeenCalledWith(workspaceId);
    expect(requireV3WorkspaceAccess).toHaveBeenCalledWith(null, workspaceId, "readWrite", "req_1", base.instance);
  });

  test("does not delete when authorization fails", async () => {
    vi.mocked(requireV3WorkspaceAccess).mockResolvedValue(new Response(null, { status: 403 }));

    const response = await deleteUnusedV3Tags({ ...base, workspaceId: otherWorkspaceId });

    expect(response.status).toBe(403);
    expect(deleteUnusedTags).not.toHaveBeenCalled();
  });

  test("answers 500 when the service fails", async () => {
    grantAccess();
    vi.mocked(deleteUnusedTags).mockResolvedValue({
      ok: false,
      error: { code: "unexpected_error", message: "boom" },
    } as Awaited<ReturnType<typeof deleteUnusedTags>>);

    const response = await deleteUnusedV3Tags({ ...base, workspaceId });

    expect(response.status).toBe(500);
  });
});
EOF
